@php($maximum = max(1, $series->max('total')))
<div class="chart" role="img" aria-label="Grafik omzet dari {{ $series->first()['label'] }} sampai {{ $series->last()['label'] }}. Data angka tersedia di bawah grafik.">@foreach($series as $point)<div class="chart-column" title="{{ $point['label'] }}: Rp{{ number_format($point['total'], 0, ',', '.') }}"><div class="chart-bar" style="height:{{ round($point['total'] / $maximum * 100, 2) }}%"></div></div>@endforeach</div>
<div class="chart-axis"><span>{{ $series->first()['label'] }}</span><span>Puncak: Rp{{ number_format($series->max('total'), 0, ',', '.') }}</span><span>{{ $series->last()['label'] }}</span></div>
<details class="chart-details" id="{{ $chartId }}"><summary>Lihat rincian angka</summary><div class="table-wrap"><table><thead><tr><th>Periode</th><th>Omzet</th></tr></thead><tbody>@foreach($series as $point)<tr><td>{{ $point['tanggal'] }}</td><td>Rp{{ number_format($point['total'], 0, ',', '.') }}</td></tr>@endforeach</tbody></table></div></details>
